  return <dialog ref={ref} onCancel={e => { e.preventDefault(); close(); }} onClick={e => { if (e.target === ref.current) close(); }}><header><h2>{title}</h2><button className="icon-button" aria-label="Закрыть" onClick={close}><X size={21}/></button></header>{children}</dialog>;
